<template>
  <main class="hh-page open-care">
    <header class="care-header">
      <div class="patient"><span>{{ initials(patientName) }}</span><div><small>ATENCIÓN HOSPITALARIA</small><h1>{{ patientName }}</h1><p>{{ patient?.identificacion || 'Identificación no informada' }} · Cama {{ bedId || '—' }}</p></div></div>
      <div class="actions"><button class="btn btn-light btn-sm plan-action" :disabled="openingPlan" @click="openPlan('medication')"><i class="ph ph-pill me-1"></i>Plan medicamentos</button><button class="btn btn-light btn-sm plan-action" :disabled="openingPlan" @click="openPlan('procedure')"><i class="ph ph-clipboard-text me-1"></i>Plan procedimientos</button><router-link v-if="hospitalizationId" :to="`/hospitalizacion/${hospitalizationId}`" target="_blank" rel="noopener noreferrer" class="btn btn-outline-light btn-sm">Hospitalización</router-link><router-link :to="`/pacientes/${patientId}`" target="_blank" rel="noopener noreferrer" class="btn btn-outline-light btn-sm">Historia clínica</router-link><button class="btn btn-outline-light btn-sm" :disabled="store.loading" @click="load"><i class="ph ph-arrows-clockwise"></i></button></div>
    </header>
    <nav class="context-bar"><router-link :to="stationId ? `/hospitalizacion/estaciones/${stationId}` : '/hospitalizacion/estaciones'"><i class="ph ph-arrow-left"></i>Volver a estación</router-link><span><i class="ph ph-file-text"></i>Orden #{{ workOrderId || '—' }}</span><span><i class="ph ph-first-aid"></i>Servicio #{{ serviceOrderId || '—' }}</span><span class="status">{{ hospitalization?.estado || 'Activo' }}</span></nav>

    <div v-if="!serviceOrderId" class="alert alert-warning mt-4"><strong>La hospitalización no tiene una orden de servicio asociada.</strong> No es posible registrar la evolución.</div>
    <div v-if="notice.text" class="alert mt-4" :class="`alert-${notice.type}`">{{ notice.text }}</div>
    <div v-if="store.loading" class="text-center py-5"><span class="spinner-border text-primary"></span><p class="text-muted mt-2">Consultando formularios autorizados…</p></div>
    <div v-else-if="store.error" class="alert alert-danger mt-4">{{ store.error }} <button class="btn btn-sm btn-outline-danger ms-2" @click="load">Reintentar</button></div>
    <template v-else>
      <section class="mt-4"><div class="section-heading"><div><span>Evolución clínica</span><h2>Espacio de evolución</h2><p>Seleccione un registro y complete el formulario sin perder el contexto del paciente.</p></div><b>{{ store.forms.length }} disponibles</b></div>
        <div v-if="!store.forms.length" class="card empty"><i class="ph ph-user-focus"></i><h3>No hay formularios clínicos disponibles</h3><p>No tiene un perfil clínico con formularios asignados para este contexto.</p></div>
        <div v-else class="care-workspace"><aside class="forms-sidebar"><header><div><small>REGISTROS DISPONIBLES</small><strong>Tipos de evolución</strong></div><span>{{ store.forms.length }}</span></header><div class="forms-list"><button v-for="form in store.forms" :key="form.id" :disabled="!config(form) || !serviceOrderId" :class="{ active: selected?.id === form.id, unavailable: !config(form) }" @click="open(form)"><span class="form-icon"><i :class="config(form)?.icon || 'ph ph-file-dashed'"></i></span><span class="form-name"><strong>{{ form.nombre }}</strong><small>{{ config(form) ? `Registro clínico #${form.id}` : unavailableReason(form) }}</small></span><i v-if="config(form)" class="ph ph-caret-right arrow"></i><i v-else class="ph ph-lock-simple arrow"></i></button></div><footer><i class="ph ph-shield-check"></i><span>Opciones autorizadas para su perfil por el servidor.</span></footer></aside><section class="form-panel"><div v-if="!selected" class="select-prompt"><span><i class="ph ph-cursor-click"></i></span><h3>Seleccione un tipo de evolución</h3><p>El formulario aparecerá en este espacio y el contexto del paciente permanecerá visible.</p></div><template v-else><header class="form-panel-header"><div><small>NUEVA EVOLUCIÓN</small><h3>{{ selected.nombre }}</h3><p>{{ patientName }} · Orden de servicio #{{ serviceOrderId }}</p></div><button class="btn btn-sm btn-outline-secondary" :disabled="store.saving" @click="close"><i class="ph ph-x me-1"></i>Cerrar</button></header><div class="form-panel-body"><component :is="selectedComponent" :saving="store.saving" @submit="save" @cancel="close" /><div v-if="formError" class="alert alert-danger mt-3 mb-0">{{ formError }}</div></div></template></section></div>
      </section>
      <section class="mt-5"><div class="section-heading"><div><span>Consulta</span><h2>Historial de evoluciones</h2><p>Los datos se cargan solamente cuando abre un tipo.</p></div><button class="btn btn-outline-primary" :disabled="historyLoading || !serviceOrderId" @click="loadHistory"><span v-if="historyLoading" class="spinner-border spinner-border-sm me-2"></span>Consultar historial</button></div>
        <div class="history"><article v-for="type in store.previousTypes" :key="type.id"><button @click="toggle(type)"><span><i class="ph ph-file-text"></i>{{ type.nombre_actividad || type.nombre || `Registro #${type.id}` }}</span><i :class="expanded === type.id ? 'ph ph-caret-up' : 'ph ph-caret-down'"></i></button><div v-if="expanded === type.id" class="records"><span v-if="recordLoading">Consultando…</span><p v-else-if="!records(type.id).length">No hay registros guardados.</p><div v-else v-for="(record,index) in records(type.id)" :key="record.id || index" class="record"><strong>#{{ record.id || index + 1 }}</strong><span>{{ record.fecha_actividad || record.created_at || 'Sin fecha' }}</span><p>{{ record.evolucion || record.observacion || record.motivo_atencion || 'Registro clínico guardado' }}</p></div></div></article></div>
      </section>
    </template>

    <PlanActivoModal v-if="viewerType" :type="viewerType" :context="context" :patient-name="patientName" :plan="viewerType === 'medication' ? plans.medicationPlan : plans.procedurePlan" @close="viewerType = null" @create="createFromViewer" />
    <PlanClinicoModal v-if="planModal" :type="planModal" :context="context" :patient-name="patientName" :active-plan="planModal === 'medication' ? plans.medicationPlan : plans.procedurePlan" @close="planModal = null" @saved="planSaved" />
  </main>
</template>

<script setup>
import { computed, defineAsyncComponent, onMounted, reactive, ref } from 'vue'
import { useRoute } from 'vue-router'
import { resolveClinicalForm } from '@/clinical/clinicalFormRegistry'
import { obtenerMensajeError } from '@/services/api'
import { consultarDetalle, consultarPaciente } from '@/services/hospitalizacion'
import { useOpenCareStore } from '@/store/pinia/atencion'
import { usePatientPlansStore } from '@/store/pinia/planesPaciente'
import PlanClinicoModal from '@/views/clinical/PlanClinicoModal.vue'
import PlanActivoModal from '@/views/clinical/PlanActivoModal.vue'
import { usePermisos } from '@/store/pinia/permisos'
// Oculta las acciones que el usuario no tiene permiso de hacer (el backend igual lo valida).
const { puede } = usePermisos()

const route = useRoute(), store = useOpenCareStore()
const plans = usePatientPlansStore()
const patientId = Number(route.params.id), hospitalizationId = Number(route.query.hospitalizacion) || null, workOrderId = Number(route.query.orden) || null, serviceOrderId = Number(route.query.ordenServicio || route.query.servicio) || null, bedId = Number(route.query.cama) || null, stationId = Number(route.query.estacion) || null
const context = { patientId, hospitalizationId, workOrderId, serviceOrderId, masterRegisterId: null, activityId: route.query.actividad ? Number(route.query.actividad) : null, stationId, bedId }
const patient = ref(null), hospitalization = ref(null), selected = ref(null), selectedComponent = ref(null), historyLoading = ref(false), recordLoading = ref(false), expanded = ref(null), formError = ref(''), planModal = ref(null), viewerType = ref(null), openingPlan = ref(false), notice = reactive({ text: '', type: 'success' })
const patientName = computed(() => patient.value?.nombre_completo || patient.value?.nombre || store.patient?.nombre || [patient.value?.primer_nombre, patient.value?.primer_apellido].filter(Boolean).join(' ') || `Paciente #${patientId}`)
const initials = name => String(name || 'P').split(' ').slice(0, 2).map(value => value[0]).join('').toUpperCase()
// Formulario habilitado solo si existe en el frontend Y el usuario tiene su permiso.
const config = form => { const item = resolveClinicalForm(form.tabla); return item && puede(item.permiso) ? item : null }
const unavailableReason = form => resolveClinicalForm(form.tabla) ? 'Sin permiso para registrar' : 'Pendiente en frontend'
const records = id => store.previousRecordsByForm[id] || []
async function load() { notice.text = ''; const base = await Promise.allSettled([consultarPaciente(patientId), hospitalizationId ? consultarDetalle(hospitalizationId) : Promise.resolve(null)]); patient.value = base[0].status === 'fulfilled' ? base[0].value?.data || base[0].value : null; hospitalization.value = base[1].status === 'fulfilled' ? base[1].value?.data || base[1].value : null; if (serviceOrderId) try { await store.loadOpenCare(context) } catch { /* El store conserva el error. */ } }
function open(form) { const item = config(form); if (!item) return; store.selectClinicalForm(form.id); selected.value = form; selectedComponent.value = defineAsyncComponent(item.component); formError.value = '' }
function close() { if (!store.saving) selected.value = null }
async function save(values) { formError.value = ''; try { await store.saveEvolution(config(selected.value), values); selected.value = null; store.previousTypes = []; notice.type = 'success'; notice.text = 'Evolución clínica guardada correctamente.' } catch (error) { formError.value = obtenerMensajeError(error) } }
async function loadHistory() { historyLoading.value = true; try { await store.loadPreviousTypes() } catch (error) { notice.type = 'danger'; notice.text = obtenerMensajeError(error) } finally { historyLoading.value = false } }
async function toggle(type) { if (expanded.value === type.id) { expanded.value = null; return } expanded.value = type.id; if (!records(type.id).length) { recordLoading.value = true; try { await store.loadPreviousRecords(type.id) } catch (error) { notice.type = 'danger'; notice.text = obtenerMensajeError(error) } finally { recordLoading.value = false } } }
async function openPlan(type, create = false) { if (![patientId, hospitalizationId, workOrderId].every(value => Number.isInteger(value) && value > 0)) { notice.type = 'danger'; notice.text = 'No fue posible validar paciente, hospitalización y orden de trabajo.'; return } openingPlan.value = true; notice.text = ''; try { if (type === 'medication') { await plans.checkMedication(context); if (create) await plans.loadMedicationCatalogs() } else { await plans.checkProcedure(context); if (create) await plans.loadServiceCatalogs(true) } create ? planModal.value = type : viewerType.value = type } catch (error) { notice.type = 'danger'; notice.text = obtenerMensajeError(error) } finally { openingPlan.value = false } }
async function createFromViewer() { const type = viewerType.value; viewerType.value = null; await openPlan(type, true) }
async function planSaved() { const type = planModal.value; planModal.value = null; notice.type = 'success'; notice.text = `Plan de ${type === 'medication' ? 'medicamentos' : 'procedimientos'} creado correctamente.`; if (type === 'medication') await plans.checkMedication(context); else await plans.checkProcedure(context) }
onMounted(async () => { await load(); if (['medication', 'procedure'].includes(route.query.plan)) await openPlan(route.query.plan) })
</script>

